import os
from pathlib import Path

import pytest


def read_public(path: str) -> str:
    """Return the text of the file at request path `path` inside the
    directory `notes` (relative to the working directory), or "".

    `path` is untrusted. Paths that wander but stay inside `notes`
    (e.g. "sub/../a.txt") are allowed. Any path that leaves `notes`
    (e.g. "..", an absolute path, "sub/../../x", or a symlink pointing
    outside `notes`) yields "". Missing, unreadable, non-file, or
    otherwise invalid names (empty, containing NUL, etc.) also yield "".
    Never raises for bad input.
    """
    if not path or "\x00" in path:
        return ""
    if os.path.isabs(path) or path.startswith(("/", "\\")):
        return ""
    if Path(path).is_absolute() or Path(path).drive:
        return ""
    try:
        base = Path("notes").resolve()
        target = (base / path).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def site(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Working dir with notes/ plus files outside notes/ that must stay hidden."""
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    (tmp_path / "x").write_text("SECRET-X", encoding="utf-8")
    evil = tmp_path / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("SECRET-EVIL", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_plain_file(site: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_reads_nested_file(site: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_wander_and_return_is_allowed(site: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"
    assert read_public("./sub/./b.txt") == "beta"


def test_parent_traversal_blocked(site: Path) -> None:
    assert read_public("../secret.txt") == ""
    assert read_public("..") == ""
    assert read_public("../") == ""


def test_deep_traversal_blocked(site: Path) -> None:
    assert read_public("sub/../../x") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("../../../../../../etc/passwd") == ""


def test_sibling_with_shared_prefix_blocked(site: Path) -> None:
    assert read_public("../notes_evil/x.txt") == ""


def test_absolute_path_blocked(site: Path) -> None:
    assert read_public(str(site / "secret.txt")) == ""
    assert read_public("/etc/passwd") == ""
    assert read_public("//etc/passwd") == ""


def test_symlink_escape_blocked(site: Path) -> None:
    link = site / "notes" / "link.txt"
    try:
        link.symlink_to(site / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_public("link.txt") == ""


def test_symlinked_directory_escape_blocked(site: Path) -> None:
    link = site / "notes" / "outdir"
    try:
        link.symlink_to(site, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks not supported")
    assert read_public("outdir/secret.txt") == ""


def test_missing_file_gives_empty(site: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""


def test_directory_gives_empty(site: Path) -> None:
    assert read_public("sub") == ""
    assert read_public("") == ""
    assert read_public(".") == ""


def test_nul_byte_gives_empty(site: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("\x00") == ""


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permission bits are not enforced for root",
)
def test_unreadable_file_gives_empty(site: Path) -> None:
    target = site / "notes" / "locked.txt"
    target.write_text("hidden", encoding="utf-8")
    target.chmod(0)
    try:
        assert read_public("locked.txt") == ""
    finally:
        target.chmod(0o644)
